import{_ as s,o as t,c as n,a4 as i}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0034 — Adresses publiques : domaine du site, préfixe par type, slug unique, route de résolution","description":"Extrait de docs/adr/0034-adresses-publiques.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0034 — Adresses publiques : domaine du site, préfixe par type, slug unique, route de résolution","description":"Extrait de docs/adr/0034-adresses-publiques.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0034-adresses-publiques.md","filePath":"developpeurs/adr/0034-adresses-publiques.md"}'),a={name:"developpeurs/adr/0034-adresses-publiques.md"};function r(o,e,u,l,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0034--adresses-publiques--domaine-du-site-préfixe-par-type-slug-unique-route-de-résolution" tabindex="-1">ADR-0034 — Adresses publiques : domaine du site, préfixe par type, slug unique, route de résolution <a class="header-anchor" href="#adr-0034--adresses-publiques--domaine-du-site-préfixe-par-type-slug-unique-route-de-résolution" aria-label="Permalink to &quot;ADR-0034 — Adresses publiques : domaine du site, préfixe par type, slug unique, route de résolution {#adr-0034--adresses-publiques--domaine-du-site-préfixe-par-type-slug-unique-route-de-résolution}&quot;">​</a></h1><p><strong>Date :</strong> 18 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit SEO du 18 septembre 2026 (bloquants « aucune route publique ne sert une fiche » et « slug libre, non unique, sans redirection » ; constats élevés sur les adresses absolues, les canoniques et le mélange des langues) ; CDC_CMS_AI_Native_v1.1 §6.1 et §9 ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0013-metadonnees-seo-dans-le-panneau-de-configuration">ADR-0013</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0021-termes-de-taxonomie-registre-par-site">ADR-0021</a>, l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0025-multilinguisme-groupe-de-traduction">ADR-0025</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0026-installation-guidee-cle-d-installation">ADR-0026</a><strong>Renvois ultérieurs :</strong> complétée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a> (24 septembre 2026 : le dépôt livre en plus un front de démarrage optionnel, client de l&#39;API publique ; le Core reste headless).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Teuthis-CMS est « headless » côté public : un front tiers lit l&#39;API et produit le site. L&#39;audit SEO du 18/09 a montré qu&#39;<strong>il ne savait pas ce qu&#39;est l&#39;adresse publique d&#39;un contenu</strong> :</p><ul><li>aucune route publique ne servait une fiche : une actualité, un événement ou une fiche d&#39;annuaire n&#39;existait publiquement que comme extrait dans une liste ;</li><li>le slug d&#39;un contenu (<code>settings.slug</code>) n&#39;avait ni format, ni unicité, et aucune route ne le lisait ; un slug modifié cassait son ancienne adresse sans redirection ;</li><li>le domaine d&#39;un site (<code>sites.domain</code>) était facultatif, non validé, non unique, et ne se saisissait qu&#39;au provisionnement d&#39;un nouveau site — jamais à l&#39;installation ;</li><li>rien ne permettait de construire une adresse absolue, donc ni sitemap, ni canonique, ni <code>hreflang</code>, ni lien d&#39;article dans un flux ;</li><li>les listes, le flux RSS et la recherche servaient toutes les langues ensemble.</li></ul><p>Ces constats ont une racine commune. Les régler un par un (un sitemap ici, un <code>&lt;link&gt;</code> RSS là) aurait produit autant de façons de composer une adresse que de surfaces.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le domaine appartient au client et se déclare à l&#39;installation.</strong> L&#39;installation guidée (ADR-0026) demande le domaine du site principal. Il reste facultatif à ce moment-là, car une collectivité installe souvent avant d&#39;avoir son nom de domaine définitif. Il se modifie ensuite depuis l&#39;écran des sites. Le domaine est un nom d&#39;hôte seul, sans schéma ni chemin, et il est <strong>unique dans l&#39;instance</strong>. <strong>Sans domaine, l&#39;API ne devine rien</strong> : les adresses absolues et les canoniques valent <code>null</code>.</p><p><strong>2. Le modèle d&#39;adresse d&#39;un contenu est <code>/{préfixe}/{slug}</code>.</strong> Le préfixe est réglable par type de contenu et se déduit par défaut de sa clé (<code>actualites</code>, <code>agenda</code>…). Un préfixe ne peut pas être celui d&#39;un autre type, le slug d&#39;une page de premier niveau, un code de langue ou un mot réservé. La règle vaut dans les deux sens : une page de premier niveau ne peut pas prendre un préfixe. Les pages gardent l&#39;adresse de leur arborescence (<code>/mairie/conseil-municipal</code>). L&#39;adresse ne porte ni date ni identifiant : elle doit rester lisible, stable, et se dire à voix haute.</p><p><strong>3. La langue par défaut du site n&#39;a pas de préfixe ; les autres en ont un court.</strong> <code>/actualites/fete-de-la-musique</code> en français sur un site français, <code>/en/actualites/music-day</code> pour sa version anglaise. Ajouter une langue ne change donc jamais une adresse existante.</p><p><strong>4. Le slug est unique par site, type de contenu et langue</strong>, exactement ce que l&#39;adresse distingue. Un contenu créé sans slug en reçoit un, tiré de son titre. Un slug saisi invalide est <strong>refusé, avec la forme corrigée proposée</strong>, plutôt que réécrit en silence. Un slug modifié laisse une <strong>redirection</strong> : l&#39;ancienne adresse continue de mener au contenu. Un contenu créé sans langue reçoit la langue par défaut de son site : c&#39;est la condition pour que l&#39;unicité voie deux contenus qui prétendraient à la même adresse.</p><p><strong>5. Une copie répliquée d&#39;un site A vers un site B a pour canonique l&#39;adresse sur A.</strong> Les moteurs n&#39;indexent ainsi qu&#39;un exemplaire, celui du service qui a écrit le contenu. Le sitemap de B n&#39;inclura pas les copies.</p><p><strong>6. Une seule route publique dit ce qu&#39;une adresse désigne</strong> : <code>GET /api/v1/public/resolve</code>, à partir d&#39;un chemin et d&#39;un hôte (ou d&#39;un identifiant de site). Elle répond par une fiche, une page ou une redirection, avec des métadonnées SEO déjà résolues : titre et description avec repli sur le contenu, canonique, versions dans les autres langues. Une adresse inconnue répond 404. <strong>Elle ne renvoie pas de 301 HTTP</strong> : un <code>fetch</code> côté front suivrait la redirection vers le site public au lieu de la lui transmettre. La route <em>décrit</em> la redirection, et c&#39;est le front qui la sert. La visibilité passe par la même clause que partout ailleurs (<code>public_visibility_clause</code>), et la fiche par la même expurgation des champs privés.</p><p><strong>7. Les listes, le flux et la recherche servent une langue à la fois</strong>, par défaut celle du site.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Préfixe de langue pour toutes les langues</strong> (<code>/fr/…</code>, <code>/en/…</code>)</td><td>Chaque adresse d&#39;un site monolingue — le cas le plus courant — porterait <code>/fr/</code> pour rien, et la racine deviendrait une redirection.</td></tr><tr><td><strong>Un domaine par langue</strong></td><td>Demande un domaine par langue à l&#39;installation : trop lourd pour une collectivité.</td></tr><tr><td><strong>Préfixe fixe, non réglable</strong></td><td>Une collectivité dont le type s&#39;appelle <code>actualites_mairie</code> aurait des adresses qu&#39;elle ne peut pas corriger.</td></tr><tr><td><strong>Adresse avec date ou identifiant</strong> (<code>/actualites/2026/09/…</code>, <code>/actualites/123-…</code>)</td><td>Moins lisible, et une date d&#39;affichage corrigée changerait l&#39;adresse.</td></tr><tr><td><strong>Réécrire en silence un slug invalide</strong></td><td>L&#39;agent découvrirait une autre adresse que celle qu&#39;il a choisie, sans l&#39;avoir décidé.</td></tr><tr><td><strong>Chaque copie répliquée canonique sur son site</strong></td><td>Deux pages identiques sur deux domaines : les moteurs en choisissent une eux-mêmes, et peuvent déclasser les deux.</td></tr><tr><td><strong>Deviner l&#39;hôte à partir de la requête</strong> quand le domaine manque</td><td>Derrière un proxy, l&#39;hôte vu par l&#39;API est son nom interne : on aurait publié des adresses fausses.</td></tr><tr><td><strong>Renvoyer un vrai 301 HTTP</strong></td><td>Voir la décision 6.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un front peut rendre n&#39;importe quelle adresse avec un seul appel, et sait quand rediriger.</li><li>Une seule fonction compose les adresses publiques : le sitemap, le flux RSS, les canoniques et les <code>hreflang</code> du lot suivant s&#39;appuieront tous dessus.</li><li>Changer un slug ne perd plus le référencement acquis.</li><li>Les métadonnées SEO validées par un agent (ADR-0013) sont enfin servies.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>La migration touche des données existantes.</strong> Elle normalise les slugs, génère les absents, départage les doublons (<code>-2</code>…) et pose la langue par défaut là où elle manquait. Chaque slug modifié laisse une redirection, mais un contenu dont le slug était invalide change d&#39;adresse.</li><li>La migration <strong>échoue</strong> si deux sites partagent déjà un domaine. Elle nomme les sites concernés, et l&#39;exploitant tranche avant de migrer.</li><li>Un contenu créé sans langue n&#39;est plus « sans langue déclarée » : il est dans la langue par défaut de son site.</li><li>Les pages restent monolingues et publiques dès leur création : c&#39;est un choix de cycle de vie, à trancher à part.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Lot suivant de l&#39;audit SEO : <code>sitemap.xml</code> par site (avec <code>hreflang</code>, sans les copies répliquées), flux RSS complet (<code>&lt;link&gt;</code> par article, langue réelle, <code>atom:link</code>), <code>robots.txt</code>, en-tête <code>X-Robots-Tag</code> → <a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a>. Le cache des routes JSON publiques reste à faire (actions de l&#39;ADR-0035).</li><li>[x] Pages multilingues et brouillon de page. <strong>Fait</strong> — brouillon de page le 04/10/2026 (<a href="/teuthis-cms-distribution/developpeurs/adr/0065-cycle-de-vie-des-pages">ADR-0065</a>) ; pages multilingues le 07/10/2026 (<a href="/teuthis-cms-distribution/developpeurs/adr/0066-pages-multilingues">ADR-0066</a>) : <code>pages.locale</code> et <code>pages.translation_group_id</code> (migration <code>0050_pages_multilingues.py</code>), unicité <code>(site_id, locale, slug)</code>, un arbre par langue, <code>locale</code> sur les routes par slug, « Traduire en … » (<code>app/page_builder/translations.py</code>), résolution <code>/en/…</code> et <code>/en</code>, <code>alternates</code>, <code>home_paths</code>, plan de site et recherche par langue. Preuve : <code>tests/test_pages_multilingues.py</code> (12 tests, rouges sur le code antérieur).</li><li>[x] Saisie SEO lisible dans le back-office, au lieu du JSON brut — fait (audit du 26/09/2026, S17) : <code>apps/admin/components/seo/</code>, pour les fiches comme pour les pages (SEO des pages : migration 0040) ; tests <code>tests/test_adresses_retirees_seo_pages_recherche.py</code>.</li></ul>',23)])])}const m=s(a,[["render",r]]);export{g as __pageData,m as default};
